-- 0092: MYP2 command-term fixes (strict pass). Rewording only; answers, marks,
-- criteria, strands, hints and accepted variants unchanged and re-verified.
begin;
update questions set prompt = 'Write down the ratio 12 : 18 in its simplest form. Type it like 2:3.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write down the ratio 12 : 18 in its simplest form. Type it like 2:3."}]}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess-prep-myp2-formative' and (config->>'question_number')::int = 5;
update questions set prompt = 'Spot the mistake. A student writes: "4 shirts cost $48. 10 shirts is 6 more shirts, so 10 shirts cost 48 + 6 = $54."', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Spot the mistake. A student writes: \"4 shirts cost "},{"type":"text","text":"$48. 10 shirts is 6 more shirts, so 10 shirts cost 48 + 6 = $"},{"type":"text","text":"54.\""}]}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Calculate the actual cost of ONE shirt.","kind":"numeric","points":1,"hints":["Ignore the student''s method. Find the unit price from 4 shirts.","Divide $48 by 4 shirts."],"answer":12,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"Calculate the correct cost of 10 shirts.","kind":"numeric","points":2,"hints":["Proportional quantities are scaled by multiplication, not addition.","Multiply the cost of one shirt by 10."],"answer":120,"tolerance":0,"unit":"$"}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess-prep-myp2-formative' and (config->>'question_number')::int = 14;
update questions set prompt = 'The universal set is ξ = {1, 2, 3, …, 12}. Set E contains the even numbers.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The universal set is ξ = {1, 2, 3, …, 12}. Set E contains the even numbers."}]}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Write down the elements of E, separated by commas.","kind":"text","points":1,"hints":["Even means exactly divisible by 2.","Work through 1 to 12 and keep the numbers divisible by 2."],"accepted":["2, 4, 6, 8, 10, 12","2,4,6,8,10,12","{2, 4, 6, 8, 10, 12}"]},{"id":"b","label":"(b)","prompt":"Calculate how many elements are in the complement of E, n(E′).","kind":"numeric","points":1,"hints":["The complement is everything in ξ that is NOT in E.","Subtract n(E) from the total number of elements in ξ."],"answer":6,"tolerance":0}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess-prep-myp2-formative' and (config->>'question_number')::int = 16;
update questions set prompt = 'Sam says: "Doubling 3 : 5 to 6 : 10 changes the ratio, because the numbers are bigger." Explain, in 1–2 sentences, whether Sam is right, and justify your answer using what the ratio 3 : 5 means.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sam says: \"Doubling 3 : 5 to 6 : 10 changes the ratio, because the numbers are bigger.\" Explain, in 1–2 sentences, whether Sam is right, and justify your answer using what the ratio 3 : 5 means."}]}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess-prep-myp2-formative' and (config->>'question_number')::int = 25;
update questions set prompt = 'A leaking pipe is investigated. The volume of water collected is measured every 2 minutes and the leak is steady.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A leaking pipe is investigated. The volume of water collected is measured every 2 minutes and the leak is steady."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Leak investigation","columns":["Time t (min)","2","4","6","10","15"],"rows":[["Volume V (L)","0.8","1.6","2.4","?","?"]]}}}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Find the volume collected after 10 minutes.","kind":"numeric","points":0.5,"hints":["Look at how the volume grows each 2 minutes.","Find the volume per minute, then multiply by 10."],"strand":"B(i)","answer":4.0,"tolerance":0.05,"unit":"L"},{"id":"b","label":"(b)","prompt":"Find the volume collected after 15 minutes.","kind":"numeric","points":0.5,"hints":["Use the same steady rate as in (a).","Multiply the per-minute rate by 15."],"strand":"B(i)","answer":6.0,"tolerance":0.05,"unit":"L"},{"id":"c","label":"(c)","prompt":"Write a general rule for V in terms of t. Type like V=0.4t.","kind":"expression","points":1,"hints":["The volume starts at 0 and grows steadily with time.","Write V = (volume per minute) × t."],"strand":"B(ii)","accepted":["V=0.4t","0.4t","V = 0.4 × t"]},{"id":"d","label":"(d)","prompt":"Verify your rule: calculate how many litres collect in one hour (60 minutes).","kind":"numeric","points":1,"hints":["Substitute t = 60 into your rule.","Multiply your per-minute rate by 60."],"strand":"B(iii)","answer":24,"tolerance":0.1,"unit":"L"}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 11;
update questions set prompt = 'A tile designer repeats a motif. The table shows the number of dark tiles and light tiles in each design size.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A tile designer repeats a motif. The table shows the number of dark tiles and light tiles in each design size."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Tile motif investigation","columns":["Size n","1","2","3","4","5"],"rows":[["Dark tiles","3","5","7","9","?"],["Light tiles","5","8","11","14","?"]]}}}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Find the number of dark tiles in size 5.","kind":"numeric","points":0.5,"hints":["Look at the step from one size to the next in the dark row.","Continue the dark-tile pattern by its constant step."],"strand":"B(i)","answer":11,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the number of light tiles in size 5.","kind":"numeric","points":0.5,"hints":["The light row has its own constant step — find it.","Continue the light-tile pattern by its step."],"strand":"B(i)","answer":17,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write a general rule for the number of dark tiles D in size n. Type like D=2n+1.","kind":"expression","points":1,"hints":["Compare each dark value with double the size number.","Use the step as the multiplier of n, then adjust with a constant."],"strand":"B(ii)","accepted":["D=2n+1","2n+1"]},{"id":"d","label":"(d)","prompt":"Verify your rule: calculate the number of dark tiles in size 20.","kind":"numeric","points":1,"hints":["Substitute n = 20 into your rule from (c).","Multiply 20 by the step and add the constant."],"strand":"B(iii)","answer":41,"tolerance":0}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 12;
update questions set prompt = 'A class investigates a biased drawing pin. It is dropped 200 times and lands point-up 130 times. The experiment is repeated in larger trials.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class investigates a biased drawing pin. It is dropped 200 times and lands point-up 130 times. The experiment is repeated in larger trials."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Drawing pin experiment","columns":["Drops","50","100","200","400"],"rows":[["Point-up","34","63","130","…"],["Relative frequency","0.68","0.63","0.65","…"]]}}}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Write down the relative frequency of point-up after 200 drops, as a decimal.","kind":"numeric","points":0.5,"hints":["Relative frequency = frequency ÷ total trials.","Divide the point-up count by 200."],"strand":"B(i)","answer":0.65,"tolerance":0.005},{"id":"b","label":"(b)","prompt":"Estimate how many point-up landings you would expect in 1000 drops, using the 200-drop result.","kind":"numeric","points":0.5,"hints":["Scale the relative frequency up to 1000 drops.","Multiply your decimal from (a) by 1000."],"strand":"B(i)","answer":650,"tolerance":0},{"id":"c","label":"(c)","prompt":"Describe, in one short phrase, what happens to the relative frequencies as the number of drops increases.","kind":"text","points":1,"hints":["Compare 0.68, 0.63 and 0.65 — are they moving in one direction?","Decide whether the values hover around one number or keep drifting."],"strand":"B(ii)","accepted":["it settles","settles","it settles near 0.65","settles near 0.65","it becomes more stable"],"keywords":[["settles","stable","steady around"]],"minKeywordGroups":1},{"id":"d","label":"(d)","prompt":"Verify your rule: calculate the number of point-up landings you predict in 400 drops, using the settled relative frequency.","kind":"numeric","points":1,"hints":["Use the relative frequency from (a) as the settled value.","Multiply 400 by your decimal from (a)."],"strand":"B(iii)","answer":260,"tolerance":0}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 13;
update questions set prompt = 'A teacher investigates club membership. In a year group, 26 students play in the orchestra (O), 19 are in the choir (C), and 8 do both. The year group has 50 students.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A teacher investigates club membership. In a year group, 26 students play in the orchestra (O), 19 are in the choir (C), and 8 do both. The year group has 50 students."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Orchestra and Choir","venn":{"leftLabel":"O","rightLabel":"C","leftOnly":"?","both":"8","rightOnly":"?","outside":"?","universalLabel":"ξ = 50 students"}}}}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Find the number of students in the orchestra only.","kind":"numeric","points":0.5,"hints":["The 26 includes students who also sing in the choir.","Subtract the ''both'' region from the orchestra total."],"strand":"B(i)","answer":18,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate how many students are in neither club.","kind":"numeric","points":0.5,"hints":["First find how many are in at least one club.","Add the club totals, subtract the double-counted overlap, then subtract from 50."],"strand":"B(i)","answer":13,"tolerance":0},{"id":"c","label":"(c)","prompt":"State the general rule connecting n(O ∪ C), n(O), n(C) and n(O ∩ C). Type like n(O)+n(C)-n(both).","kind":"text","points":1,"hints":["Why did you subtract the overlap in part (b)?","The overlap is counted twice when the two sets are added."],"strand":"B(ii)","accepted":["n(O)+n(C)-n(both)","n(O) + n(C) − n(O ∩ C)","add both sets then subtract the overlap","n(O)+n(C)-n(O∩C)"],"keywords":[["add","sum"],["subtract","minus"],["overlap","both","intersection","counted twice"]],"minKeywordGroups":2},{"id":"d","label":"(d)","prompt":"Verify the rule: calculate the value of n(O) + n(C) − n(both).","kind":"numeric","points":1,"hints":["Substitute the three given totals into your rule.","Add the two club sizes and subtract the both count."],"strand":"B(iii)","answer":37,"tolerance":0}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 14;
update questions set prompt = 'The graph shows the cost of hiring a kayak, where cost is proportional to time.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The graph shows the cost of hiring a kayak, where cost is proportional to time."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"term_graph","title":"Kayak hire cost","xLabel":"Time (hours)","yLabel":"Cost ($)","xMin":0,"xMax":6,"yMin":0,"yMax":30,"points":[[0,0],[1,5],[2,10],[3,15],[4,20],[5,25],[6,30]],"joinPoints":true}}}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Find the cost of 3 hours using the graph.","kind":"numeric","points":1,"hints":["Find 3 on the time axis, go up to the line, then across.","Read the cost value level with 3 hours on the graph."],"strand":"C(iii)","answer":15,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"Calculate how many hours can be hired for $25.","kind":"numeric","points":1,"hints":["Start from $25 on the cost axis this time.","Go across to the line from 25, then down to the time axis."],"strand":"C(iii)","answer":5,"tolerance":0,"unit":"hours"}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 18;
update questions set prompt = 'Find the error. A student writes: "A train travels 180 km in 3 hours, so its speed is 180 × 3 = 540 km/h."', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the error. A student writes: \"A train travels 180 km in 3 hours, so its speed is 180 × 3 = 540 km/h.\""}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Train journey","columns":["Distance","180 km"],"rows":[["Time","3 hours"]]}}}]}'::jsonb, config = config || '{"parts":[{"id":"a","label":"(a)","prompt":"Calculate the correct speed. Give your answer in km/h.","kind":"numeric","points":1,"hints":["Speed is distance per unit of time — which operation gives ''per hour''?","Divide the distance by the time."],"strand":"C(iv)","answer":60,"tolerance":0,"unit":"km/h"},{"id":"b","label":"(b)","prompt":"Explain the student''s error in one short sentence.","kind":"text","points":1,"hints":["Compare the student''s operation with the correct one.","Name the operation they used and the one they should have used."],"strand":"C(iv)","accepted":["they multiplied instead of dividing","multiplied instead of dividing","they multiplied rather than divided"],"keywords":[["multiplied","multiply","times"],["divid","division"]],"minKeywordGroups":2}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 19;
commit;
